import React, { useState } from "react";

export default function AdminDashboard({ reports, ngoList, token, setMsg }) {
  const [approveMsg, setApproveMsg] = useState("");
  const [ngos, setNgos] = useState(null);
  const [eventStats, setEventStats] = useState(null);

  function approveNGO(id) {
    // Approve NGO is not implemented in demo backend.
    setApproveMsg('Approve action is not available in demo.');
  }

  return (
    <div className="panel">
      <h3>Admin Reports</h3>

      <div className="cards">
        <div className="stat-card">
          <div className="stat-num">{reports ? (reports.donations ? reports.donations.reduce((s,d)=>s+parseFloat(d.amount||0),0) : 0) : '-'}</div>
          <div className="stat-label">Total Donation Amount (₹)</div>
        </div>
        <div className="stat-card">
          <div className="stat-num">{reports ? (reports.volunteers ? reports.volunteers.length : 0) : '-'}</div>
          <div className="stat-label">Total Volunteers</div>
        </div>
        <div className="stat-card">
          <div className="stat-num">{reports ? (reports.feedbacks ? reports.feedbacks.length : 0) : '-'}</div>
          <div className="stat-label">Feedbacks</div>
        </div>
      </div>

      <h4>Approve NGOs</h4>
      <div style={{marginTop:12}}>
        <button onClick={async ()=>{
          if (!token) { setMsg('Login as admin to view NGOs'); return; }
          const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngos',{headers:{Authorization:`Bearer ${token}`}});
          const d = await res.json(); setNgos(d.ngos || []);
        }}>View Registered NGOs</button>

        <button style={{marginLeft:8}} onClick={async ()=>{
          if (!token) { setMsg('Login as admin to view events'); return; }
          const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/registered-events',{headers:{Authorization:`Bearer ${token}`}});
          const d = await res.json(); setEventStats(d.events || []);
        }}>View Registered Events</button>

        <button style={{marginLeft:8}} onClick={async ()=>{
          if (!token) { setMsg('Login as admin to view events stats'); return; }
          const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/event-stats',{headers:{Authorization:`Bearer ${token}`}});
          const d = await res.json(); setEventStats(d.events || []);
        }}>View Event Stats</button>
      </div>

      <div style={{display:'flex',gap:16}}>
        <div style={{flex:1}}>
          {ngos ? (ngos.length ? (
            <div style={{display:'grid',gap:8}}>
              {ngos.map(n=>(<div key={n.id} style={{padding:8,background:'#fff',borderRadius:8,display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><strong>{n.name}</strong><div style={{fontSize:13,color:'#666'}}>{n.email}</div></div><button onClick={async ()=>{ if (!token) { setMsg('Login as admin'); return;} const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + "/api/actions/ngo/"+n.id,{headers:{Authorization:`Bearer ${token}`}}); const d = await res.json(); setEventStats(d.events || []); setNgos(prev=>prev); }}>View Details</button></div>))}
            </div>
          ) : <p>No NGOs registered.</p>) : (
            <p>Loading NGOs...</p>
          )}
        </div>

        <div style={{width:420}}>
          <h4>Selected NGO / Events</h4>
          {eventStats && eventStats.length ? eventStats.map(ev=>(
            <div key={ev.id} style={{display:'flex',gap:12,alignItems:'center',padding:8,background:'#fff',borderRadius:8,marginBottom:8}}>
              <img src={ev.image_url||'https://via.placeholder.com/120x80'} style={{width:100,height:64,objectFit:'cover',borderRadius:6}} />
              <div style={{flex:1}}>
                <div style={{fontWeight:600}}>{ev.title}</div>
                <div style={{fontSize:13,color:'#666'}}>Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}</div>
              </div>
            </div>
          )) : <div>Select an NGO and click "View Details" to load events.</div>}
        </div>
      </div>

      {eventStats && (
        <div style={{marginTop:12}}>
          <h4>Event Statistics</h4>
          {eventStats.map(ev=>(
            <div key={ev.id} style={{display:'flex',alignItems:'center',gap:12,marginBottom:8}}>
              <img src={ev.image_url||'https://via.placeholder.com/120x80'} alt="ev" style={{width:120,height:70,objectFit:'cover',borderRadius:6}} />
              <div style={{flex:1}}>
                <div style={{fontWeight:600}}>{ev.title}</div>
                <div style={{fontSize:13,color:'#666'}}>Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}</div>
              </div>
            </div>
          ))}
        </div>
      )}

      {approveMsg && <p className="msg">{approveMsg}</p>}
    </div>
  );
}
